// ================= INPUT =================
const input = $input.first()?.json;
let reportText;

if (!input) throw new Error('No input data provided');

if (typeof input === 'string') {
  reportText = input.trim();
} else if (input.output) {
  reportText = input.output.trim();
} else {
  throw new Error('Invalid input format');
}

// ================= HELPER =================
function textToHtml(sectionText) {
  if (!sectionText) return '<p>No data available</p>';

  if (sectionText.match(/^- /gm) || sectionText.match(/^\d+\. /gm)) {
    const lis = sectionText
      .replace(/^- /gm, '<li>')
      .replace(/^\d+\. /gm, '<li>')
      .replace(/\n/g, '</li>');
    return '<ul>' + lis + '</ul>';
  } else {
    return '<p>' + sectionText.replace(/\n/g, '<br>') + '</p>';
  }
}

function extractSection(text, start, end) {
  const regex = new RegExp(start + "[\\s\\S]*?" + (end ? "(?=" + end + ")" : "$"), "i");
  const match = text.match(regex);
  return match ? match[0].replace(new RegExp(start, "i"), "").trim() : "";
}

function extractNumber(text, label) {
  const regex = new RegExp(label + "[:\\s]*\\$?([\\d.,]+)", "i");
  const match = text.match(regex);
  return match ? parseFloat(match[1].replace(/,/g, '')) : 0;
}

// ================= EXTRACT SECTIONS =================
let title = "Financial Analysis Report";

let overviewSection = extractSection(reportText, "Overview", "Income");
let incomeSection = extractSection(reportText, "Income", "Expenses");
let expensesSection = extractSection(reportText, "Expenses", "Trends");
let trendsSection = extractSection(reportText, "Trends", "Summary");
let summarySection = extractSection(reportText, "Summary", null);

// Title
const titleMatch = reportText.match(/^(.*?)(?=Overview)/i);
if (titleMatch) title = titleMatch[1].trim();

// ================= NUMBERS =================
let beginningBalance = extractNumber(overviewSection, "Beginning Balance");
let endingBalance = extractNumber(overviewSection, "Ending Balance");
let totalIncome = extractNumber(overviewSection, "Total Income");
let totalExpenses = extractNumber(overviewSection, "Total Expenses");

// ================= TRANSACTIONS =================
const transactions = [];
const expenseCats = [];
const expenseAmts = [];

// 🔥 INCOME PARSING (VERY FLEXIBLE)
incomeSection.split('\n').forEach(line => {
  const match = line.match(/(.*?):\s*\$?([\d.,]+).*?(\d{4}-\d{2}-\d{2})/);
  if (match) {
    const amt = parseFloat(match[2].replace(/,/g, ''));
    const date = match[3];
    transactions.push({ date, amount: amt, desc: match[1] });
    totalIncome += amt; // fallback if missing
  }
});

// 🔥 EXPENSE PARSING (VERY FLEXIBLE)
expensesSection.split('\n').forEach(line => {
  const match = line.match(/(.*?):\s*\$?([\d.,]+)/);
  if (match) {
    const category = match[1].trim();
    const amt = parseFloat(match[2].replace(/,/g, ''));

    expenseCats.push(category);
    expenseAmts.push(amt);

    const dateMatch = line.match(/(\d{4}-\d{2}-\d{2})/);
    const date = dateMatch ? dateMatch[1] : "2025-01-01";

    transactions.push({ date, amount: -amt, desc: category });
    totalExpenses += amt; // fallback
  }
});

// ================= SAFETY FIX =================
if (totalIncome === 0) totalIncome = 1;
if (totalExpenses === 0) totalExpenses = 1;

if (expenseCats.length === 0) {
  expenseCats.push("No Data");
  expenseAmts.push(1);
}

// ================= BALANCE TREND =================
transactions.sort((a, b) => new Date(a.date) - new Date(b.date));

let balance = beginningBalance || 0;
const dataPoints = [];

transactions.forEach(t => {
  balance += t.amount;
  dataPoints.push({ date: t.date, balance });
});

// fallback if no transactions
if (dataPoints.length === 0) {
  dataPoints.push({ date: "2025-01-01", balance: balance });
}

// ================= CHARTS =================
const encodeChart = config =>
  `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(config))}`;

// Bar chart
const barUrl = encodeChart({
  type: 'bar',
  data: {
    labels: ['Income', 'Expenses'],
    datasets: [{ data: [totalIncome, totalExpenses] }]
  }
});

// Pie chart
const pieUrl = encodeChart({
  type: 'pie',
  data: {
    labels: expenseCats,
    datasets: [{ data: expenseAmts }]
  }
});

// Line chart
const lineUrl = encodeChart({
  type: 'line',
  data: {
    labels: dataPoints.map(d => d.date),
    datasets: [{ label: 'Balance', data: dataPoints.map(d => d.balance) }]
  }
});

// ================= HTML =================
const html = `
<html>
<head>
<style>
body { font-family: Arial; max-width: 800px; margin:auto; padding:20px; }
h1,h2,h3 { color:#333; }
ul { padding-left:20px; }
img { max-width:100%; margin:10px 0; }
</style>
</head>
<body>

<h1>${title}</h1>

<h2>Overview</h2>
${textToHtml(overviewSection)}

<h3>Income vs Expenses</h3>
<img src="${barUrl}" />

<h2>Income</h2>
${textToHtml(incomeSection)}

<h2>Expenses</h2>
${textToHtml(expensesSection)}

<h3>Expense Breakdown</h3>
<img src="${pieUrl}" />

<h3>Balance Trend</h3>
<img src="${lineUrl}" />

<h2>Trends & Insights</h2>
${textToHtml(trendsSection)}

<h2>Summary & Recommendations</h2>
${textToHtml(summarySection)}

</body>
</html>
`;

// ================= OUTPUT =================
return [{ json: { html } }];
